enum FeatureCategory {
  core,
  orders,
  customers,
  tables,
  kitchen,
  inventory,
  staff,
  finance,
  marketing,
  analytics,
  communication,
  security,
  reports,
  selfService,
  superAdmin;

  String get label {
    switch (this) {
      case FeatureCategory.core: return 'Core';
      case FeatureCategory.orders: return 'Order Management';
      case FeatureCategory.customers: return 'Customer Engagement';
      case FeatureCategory.tables: return 'Table & Sessions';
      case FeatureCategory.kitchen: return 'Kitchen & Menu';
      case FeatureCategory.inventory: return 'Inventory';
      case FeatureCategory.staff: return 'Staff';
      case FeatureCategory.finance: return 'Finance';
      case FeatureCategory.marketing: return 'Marketing';
      case FeatureCategory.analytics: return 'Analytics';
      case FeatureCategory.communication: return 'Communication';
      case FeatureCategory.security: return 'Security';
      case FeatureCategory.reports: return 'Reports';
      case FeatureCategory.selfService: return 'Self-Service';
      case FeatureCategory.superAdmin: return 'Super Admin';
    }
  }
}

class PlatformFeature {
  final String id;
  final String name;
  final String description;
  final FeatureCategory category;
  final bool defaultEnabled;
  final List<String> dependsOn;

  const PlatformFeature({
    required this.id,
    required this.name,
    required this.description,
    required this.category,
    this.defaultEnabled = true,
    this.dependsOn = const [],
  });
}

